import { z } from 'zod';
import type { ImportDecision, ImportDraftV2 } from './adminApi';

/**
 * Identity candidates and the preselections Review and the publication confirmation show; the server mirror is
 * src/administration/import/adminImportIdentity.ts, which recomputes them at approval. Loaded only by those lazy chunks, never
 * by the import page itself. Owner rules: docs/business-rules.md (Administrator Album Imports).
 */
const id = z.string().regex(/^[a-f0-9]{24}$/), uuid = z.string().regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
const mbid = z.string().regex(/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/);
/**
 * At most 20 candidates per Artist name (the saved entries' and those pending Luna proposals would write, 40 names), per label
 * name and per Album title (the saved one and one proposed each), 20 for the saved and 20 for the proposed track titles, one
 * verified byte match per staged file (100), at most 300 byte or title matches among Album members, one record holding each
 * entry's or the label's MusicBrainz ID (21) and 20 records named as lookup found for each such ID (420): 1761. `musicBrainzId`
 * names the ID an Artist or Organization holds; `aliasOf` the ID whose found name matched. A response without
 * `memberMatchesComplete` counts as incomplete, so no append file is preselected from it. `unavailable` names the Artist names, labels or Album titles (at most 44) whose same-name, same-ID or alias record is
 * malformed: never a candidate, yet never preselected over.
 */
export const candidatesSchema = z.object({
  items: z.array(z.object({ kind: z.enum(['artist', 'organization', 'album', 'track']), id, label: z.string(), revision: z.string(), albumId: id.nullable(), visibility: z.enum(['public', 'hidden']),
    match: z.enum(['name', 'sha256', 'musicBrainzId', 'alias']), matchedSlotIds: z.array(uuid).max(100), automaticReuse: z.literal(false), musicBrainzId: mbid.optional(), aliasOf: mbid.optional() }).strict()).max(1761),
  memberMatchesComplete: z.boolean().default(false),
  unavailable: z.array(z.object({ kind: z.enum(['artist', 'organization', 'album']), label: z.string() }).strict()).max(44).default([])
}).strict();
export type ImportCandidates = z.infer<typeof candidatesSchema>;
export type ImportCandidate = ImportCandidates['items'][number];

/** The server's case folding (NFC, then locale-independent lower case), so a Turkish browser locale matches as the server does. */
export const sameName = (left: string, right: string) => left.normalize('NFC').toLowerCase() === right.normalize('NFC').toLowerCase();
/** An Artist's or label Organization's candidates: by name, by the MusicBrainz ID it carries, or by a name lookup found for that ID. */
export const rowCandidates = (kind: ImportCandidate['kind'], name: string, musicBrainzId: string | null, items: readonly ImportCandidate[]) =>
  items.filter(item => item.kind === kind && (sameName(item.label, name) || (musicBrainzId !== null && (item.musicBrainzId === musicBrainzId || item.aliasOf === musicBrainzId))));
/** The ready record holding a MusicBrainz ID, among the candidates. */
const exactHolder = (kind: 'artist' | 'organization', musicBrainzId: string | null, items: readonly ImportCandidate[]) =>
  musicBrainzId === null ? undefined : items.find(item => item.kind === kind && item.match === 'musicBrainzId' && item.musicBrainzId === musicBrainzId);
const choice = (scope: ImportDecision['scope'], slotId: string | null, entryKey: string | null, boundName: string | null, reused?: ImportCandidate): ImportDecision =>
  ({ scope, slotId, entryKey, boundName, action: reused ? 'reuse' : 'create-distinct', candidateId: reused?.id ?? null, candidateRevision: reused?.revision ?? null });

/**
 * The decisions preselected for rows of `draft` without an explicit decision in `decisions`, from `candidates` read for the drafts
 * in `read` (the saved draft and, for the confirmation, the saved draft with every pending Luna proposal written in). A row whose
 * shown value no read draft holds (an entry by key, name and MusicBrainz ID, the label by name and ID, the Album title and, in an
 * append, a track title) is never preselected: its candidates were not read for it. Otherwise as on the server:
 * without an explicit Album reuse, an entry or the label whose ID a listed record holds reuses it unless another row's reuse (or
 * replace) or an earlier preselection names it; an entry, the label and the Album with no name, alias or same-ID candidate of
 * their kind are created, and once the
 * Album is created so is every track; when appending, a file matching no target member is a new member, and one whose verified
 * bytes match exactly one member, matched by no other file and reused by no other decision, reuses it, all only while the member
 * matches are complete. A name listed as `unavailable` counts as a candidate. Any other row needs an explicit choice.
 */
export function identityPreselections(draft: ImportDraftV2, read: readonly ImportDraftV2[], decisions: readonly ImportDecision[], candidates: ImportCandidates): ImportDecision[] {
  const { items, unavailable } = candidates, result: ImportDecision[] = [], album = decisions.find(decision => decision.scope === 'album');
  const listed = (kind: ImportCandidate['kind'], name: string) => items.some(item => item.kind === kind && sameName(item.label, name)) || unavailable.some(entry => entry.kind === kind && sameName(entry.label, name));
  const decided = (slotId: string) => decisions.some(decision => decision.scope === 'track' && decision.slotId === slotId);
  if (album?.action === 'reuse') {
    if (!candidates.memberMatchesComplete) return result;
    const reused = new Set(decisions.filter(decision => decision.scope === 'track' && decision.action === 'reuse').map(decision => decision.candidateId));
    for (const track of draft.tracks) {
      if (decided(track.slotId) || !read.some(saved => saved.tracks.find(item => item.slotId === track.slotId)?.title === track.title)) continue;
      const bytes = (item: ImportCandidate) => item.match === 'sha256' && item.matchedSlotIds.includes(track.slotId);
      const members = items.filter(item => item.kind === 'track' && item.albumId === album.candidateId && (bytes(item) || (track.title !== '' && sameName(item.label, track.title))));
      const identical = members.filter(bytes);
      if (!members.length) result.push(choice('track', track.slotId, null, null));
      else if (identical.length === 1 && identical[0].matchedSlotIds.length === 1 && !reused.has(identical[0].id)) result.push(choice('track', track.slotId, null, null, identical[0]));
    }
    return result;
  }
  const taken = (scope: 'artist' | 'label', candidateId: string) => [...decisions, ...result].some(decision => decision.scope === scope && (decision.action === 'reuse' || decision.action === 'replace') && decision.candidateId === candidateId);
  const preselect = (scope: 'artist' | 'label', kind: 'artist' | 'organization', entryKey: string | null, name: string, musicBrainzId: string | null) => {
    const exact = exactHolder(kind, musicBrainzId, items);
    if (exact && !taken(scope, exact.id)) result.push(choice(scope, null, entryKey, name, exact));
    else if (!listed(kind, name) && !rowCandidates(kind, name, musicBrainzId, items).length) result.push(choice(scope, null, entryKey, name));
  };
  for (const entry of draft.album.artists) {
    if (!decisions.some(decision => decision.scope === 'artist' && decision.entryKey === entry.key)
      && read.some(saved => saved.album.artists.some(item => item.key === entry.key && item.name === entry.name && item.musicBrainzId === entry.musicBrainzId)))
      preselect('artist', 'artist', entry.key, entry.name, entry.musicBrainzId);
  }
  const label = draft.album.label;
  if (label && !decisions.some(decision => decision.scope === 'label') && read.some(saved => saved.album.label?.name === label.name && saved.album.label.musicBrainzId === label.musicBrainzId))
    preselect('label', 'organization', null, label.name, label.musicBrainzId);
  const created = album ? album.action === 'create-distinct' : read.some(saved => saved.album.title === draft.album.title) && !listed('album', draft.album.title);
  if (!album && created) result.push(choice('album', null, null, null));
  if (created) for (const track of draft.tracks) if (!decided(track.slotId)) result.push(choice('track', track.slotId, null, null));
  return result;
}

/**
 * Slots whose verified bytes match a ready MediaTrack outside the explicit append target (another Album, or none): a possible
 * duplicate that is flagged and never collapsed, but needs no answer and changes no preselection.
 */
export function duplicateFileSlots(decisions: readonly ImportDecision[], candidates: ImportCandidates): ReadonlySet<string> {
  const target = decisions.find(decision => decision.scope === 'album' && decision.action === 'reuse')?.candidateId ?? null;
  return new Set(candidates.items.filter(item => item.kind === 'track' && item.match === 'sha256' && (item.albumId === null || item.albumId !== target)).flatMap(item => item.matchedSlotIds));
}

/** One MusicBrainz ID a publication records (`replaces` null) or replaces; the server's ImportMusicBrainzIdWrite. */
export type MusicBrainzIdWrite = { scope: 'artist' | 'label'; entryKey: string | null; musicBrainzId: string; replaces: string | null };
/**
 * The MusicBrainz IDs an approval of `draft` records or replaces, in draft order (entries, then the label), from the decision or
 * preselection each row reads: a new record keeps its entry's ID unless a listed record holds it; reusing a record without an ID
 * records it while no other listed record holds it; `replace` puts it in place of the ID the record holds. Mirrors the server's
 * musicBrainzIdWriteFor (src/administration/import/adminImportMusicBrainzIds.ts); an append records none.
 */
export function musicBrainzIdWrites(draft: ImportDraftV2, decisions: readonly ImportDecision[], preselections: readonly ImportDecision[], candidates: ImportCandidates): MusicBrainzIdWrite[] {
  const effective = (match: (decision: ImportDecision) => boolean) => decisions.find(match) ?? preselections.find(match);
  if (effective(decision => decision.scope === 'album')?.action === 'reuse') return [];
  const writes: MusicBrainzIdWrite[] = [];
  const write = (scope: 'artist' | 'label', kind: 'artist' | 'organization', entryKey: string | null, musicBrainzId: string | null, decision: ImportDecision | undefined) => {
    if (!musicBrainzId || !decision || decision.action === 'skip') return;
    const holder = exactHolder(kind, musicBrainzId, candidates.items)?.id ?? null;
    const stored = decision.action === 'create-distinct' ? null : candidates.items.find(item => item.kind === kind && item.id === decision.candidateId)?.musicBrainzId ?? null;
    if (decision.action === 'create-distinct') { if (!holder) writes.push({ scope, entryKey, musicBrainzId, replaces: null }); return; }
    if (decision.action === 'replace') { if (stored && stored !== musicBrainzId && !holder) writes.push({ scope, entryKey, musicBrainzId, replaces: stored }); return; }
    if (stored === null && (!holder || holder === decision.candidateId)) writes.push({ scope, entryKey, musicBrainzId, replaces: null });
  };
  for (const entry of draft.album.artists) write('artist', 'artist', entry.key, entry.musicBrainzId, effective(decision => decision.scope === 'artist' && decision.entryKey === entry.key));
  if (draft.album.label) write('label', 'organization', null, draft.album.label.musicBrainzId, effective(decision => decision.scope === 'label'));
  return writes;
}
